const NOME_ATTIVITA = 'Barberia Demo';
const GIORNI_RICHIAMO = 45;
const LINK_RECENSIONE = 'https://g.page/r/LINK-RECENSIONE-DA-METTERE';
const oggi = $today.toFormat('yyyy-MM-dd');
function giorniTra(a, b) { return Math.round((new Date(b) - new Date(a)) / 86400000); }
const risultati = [];
for (const it of $input.all()) {
  const c = it.json;
  if (!c.ultima_visita) continue;
  const nome = String(c.nome || '').split(' ')[0];
  const giorni = giorniTra(c.ultima_visita, oggi);
  let richiamo = c.richiamo_inviato_il || '';
  let tornato = c.tornato_dopo_richiamo === true;
  let recensione = c.recensione_chiesta_il || '';
  const azioni = [];
  if (richiamo && !tornato && c.ultima_visita > richiamo && giorniTra(richiamo, c.ultima_visita) <= 30) {
    tornato = true;
    azioni.push({ tipo: 'tornato', testo: 'tornato il ' + c.ultima_visita + ' dopo il richiamo del ' + richiamo + ' (circa ' + (c.scontrino_medio || 0) + ' euro)' });
  }
  if (c.consenso_marketing === true && giorni === 1 && (!recensione || recensione < c.ultima_visita)) {
    recensione = oggi;
    azioni.push({ tipo: 'recensione', testo: 'Ciao ' + nome + ', grazie per essere passato ieri da ' + NOME_ATTIVITA + '! Se ti va, lasciaci una recensione su Google: ci aiuta tantissimo. ' + LINK_RECENSIONE + ' (Scrivi STOP per non ricevere più messaggi)' });
  }
  if (c.consenso_marketing === true && giorni >= GIORNI_RICHIAMO && (!richiamo || richiamo < c.ultima_visita)) {
    richiamo = oggi;
    tornato = false;
    azioni.push({ tipo: 'richiamo', testo: 'Ciao ' + nome + ', è passato un po’ dall’ultimo taglio da ' + NOME_ATTIVITA + '. Vuoi che ti tenga un posto questa settimana? Rispondi con il giorno che preferisci. (Scrivi STOP per non ricevere più messaggi)' });
  }
  if (azioni.length === 0) continue;
  risultati.push({ id: c.id, nome: c.nome, telefono: c.telefono, richiamo_inviato_il: richiamo, tornato_dopo_richiamo: tornato, recensione_chiesta_il: recensione, azioni: azioni });
}
if (risultati.length === 0) return [];
const righe = ['Barberia Demo - ' + oggi, 'ANTEPRIMA: questi messaggi partirebbero su WhatsApp', ''];
for (const r of risultati) {
  for (const a of r.azioni) {
    if (a.tipo === 'tornato') righe.push('TORNATO: ' + r.nome + ' - ' + a.testo);
    else righe.push((a.tipo === 'richiamo' ? 'RICHIAMO' : 'RECENSIONE') + ' a ' + r.nome + ' (' + r.telefono + '):\n' + a.testo);
    righe.push('');
  }
}
const riepilogo = righe.join('\n');
return risultati.map(function (r) { return { json: Object.assign({}, r, { riepilogo: riepilogo }) }; });

const NOME_ATTIVITA = 'Barberia Demo';
const mese = $today.minus({ months: 1 });
const ym = mese.toFormat('yyyy-MM');
const nomeMese = mese.setLocale('it').toFormat('LLLL yyyy');
const clienti = $input.all().map(function (i) { return i.json; });
function nelMese(d) { return typeof d === 'string' && d.slice(0, 7) === ym; }
const richiami = clienti.filter(function (c) { return nelMese(c.richiamo_inviato_il); });
const tornati = clienti.filter(function (c) { return c.tornato_dopo_richiamo === true && nelMese(c.ultima_visita); });
const recensioni = clienti.filter(function (c) { return nelMese(c.recensione_chiesta_il); });
const euro = tornati.reduce(function (s, c) { return s + (Number(c.scontrino_medio) || 0); }, 0);
const righe = [
  'Report ' + nomeMese + ' - ' + NOME_ATTIVITA,
  '',
  'Richiami inviati: ' + richiami.length,
  'Clienti tornati dopo il richiamo: ' + tornati.length + (tornati.length ? ' (' + tornati.map(function (c) { return c.nome; }).join(', ') + ')' : ''),
  'Incasso da chi è tornato: circa ' + euro + ' euro',
  'Richieste di recensione inviate: ' + recensioni.length,
  '',
  'Nota: è una stima (scontrino medio di chi è tornato entro 30 giorni dal richiamo). Qualcuno sarebbe tornato comunque.'
];
return [{ json: { mese: nomeMese, richiami: richiami.length, tornati: tornati.length, euro: euro, recensioni: recensioni.length, testo: righe.join('\n') } }];
